'use strict';

const { readdirSync, readFileSync } = require('node:fs');
const { join } = require('node:path');

// The WebAssembly module, generated by wasm-bindgen for Node and loaded synchronously.
const wasm = require('./wasm/rely_office_wasm.js');

/** An error of rely-office, with the stable code of what went wrong. */
class RelyOfficeError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'RelyOfficeError';
    this.code = code;
  }
}

const CODED_MESSAGE = /^([A-Z_]+): ([\s\S]*)$/;

/** Run a wasm call, turning its coded `Error` into a `RelyOfficeError`. */
function call(operation) {
  try {
    return operation();
  } catch (error) {
    const match = error instanceof Error ? CODED_MESSAGE.exec(error.message) : null;
    if (match) {
      throw new RelyOfficeError(match[1], match[2]);
    }
    throw error;
  }
}

/** The document as a `Uint8Array`; a Node `Buffer` already is one. */
function toBytes(input) {
  if (input instanceof Uint8Array) {
    return input;
  }
  if (input instanceof ArrayBuffer) {
    return new Uint8Array(input);
  }
  if (ArrayBuffer.isView(input)) {
    return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  }
  throw new TypeError('rely-office: the document must be a Uint8Array, a Buffer or an ArrayBuffer');
}

function toFileName(fileName) {
  return fileName === undefined || fileName === null ? undefined : String(fileName);
}

function toLimitsJson(limits) {
  return limits === undefined || limits === null ? undefined : JSON.stringify(limits);
}

function detectFormat(bytes, fileName) {
  return wasm.detectFormat(toBytes(bytes), toFileName(fileName));
}

function extractText(bytes, fileName, limits) {
  const json = call(() =>
    wasm.extractTextJson(toBytes(bytes), toFileName(fileName), toLimitsJson(limits)),
  );
  return JSON.parse(json);
}

function readSheets(bytes, fileName, limits) {
  const json = call(() =>
    wasm.readSheetsJson(toBytes(bytes), toFileName(fileName), toLimitsJson(limits)),
  );
  return JSON.parse(json);
}

function readDocumentTree(bytes, limits, options, fileName) {
  const handle = call(() =>
    wasm.readDocumentTreeHandle(
      toBytes(bytes),
      toLimitsJson(limits),
      options === undefined ? undefined : JSON.stringify(options),
      fileName === undefined || fileName === null ? undefined : String(fileName),
    ),
  );
  try {
    const tree = JSON.parse(handle.json);
    tree.media = tree.media.map((item) => ({
      index: item.index,
      contentType: item.contentType,
      bytes: handle.takeMediaBytes(item.index) ?? new Uint8Array(0),
    }));
    if (tree.objects !== undefined) {
      tree.objects = tree.objects.map((item) => ({
        media: item.media,
        program: item.program,
        name: item.name,
        package: item.package,
        bytes: handle.takeObjectBytes(item.index) ?? new Uint8Array(0),
      }));
    }
    const macroProject = handle.takeMacroProject();
    if (macroProject !== undefined) {
      tree.macroProject = macroProject;
    }
    return tree;
  } finally {
    handle.free();
  }
}

/** A doc, an odt or a docx as a docx. */
function convertToDocx(bytes, limits) {
  return call(() => wasm.convertToDocx(toBytes(bytes), toLimitsJson(limits)));
}

/** A ppt, an odp or a pptx as a pptx. */
function convertToPptx(bytes, limits) {
  return call(() => wasm.convertToPptx(toBytes(bytes), toLimitsJson(limits)));
}

/** A pptx, an odp or a ppt as slides for an editor, with the bytes of its images. */
function readPresentation(bytes, limits) {
  const handle = call(() => wasm.readPresentationHandle(toBytes(bytes), toLimitsJson(limits)));
  try {
    const presentation = JSON.parse(handle.json);
    presentation.media = presentation.media.map((item) => ({
      index: item.index,
      contentType: item.contentType,
      bytes: handle.takeMediaBytes(item.index) ?? new Uint8Array(0),
    }));
    const macroProject = handle.takeMacroProject();
    if (macroProject !== undefined) {
      presentation.macroProject = macroProject;
    }
    return presentation;
  } finally {
    handle.free();
  }
}

/** Slides as a pptx, with the images they name by index. */
function writeSlides(presentation, write) {
  const { widthEmu, heightEmu, slides, media, macroProject } = presentation ?? {};
  const writer = new wasm.PptxWriter();
  try {
    for (const item of media ?? []) {
      writer.addMedia(toBytes(item instanceof Uint8Array ? item : item.bytes));
    }
    if (macroProject !== undefined && macroProject !== null) {
      call(() => writer.setMacroProject(toBytes(macroProject)));
    }
    return call(() => write(writer, JSON.stringify({ widthEmu, heightEmu, slides: slides ?? [] })));
  } finally {
    writer.free();
  }
}

function writePptx(presentation) {
  return writeSlides(presentation, (writer, json) => writer.write(json));
}

function writeOdp(presentation) {
  return writeSlides(presentation, (writer, json) => writer.writeOdp(json));
}

let bundledRenderer = null;

/** The typesetter with the fonts of the package, set up on the first render only. */
function renderer() {
  if (bundledRenderer === null) {
    const { Renderer } = require('./wasm/rely_office_render_wasm.js');
    const created = new Renderer();
    const fontsDirectory = join(__dirname, 'fonts');
    for (const name of readdirSync(fontsDirectory).filter((file) => file.endsWith('.ttf')).sort()) {
      created.addFont(readFileSync(join(fontsDirectory, name)));
    }
    bundledRenderer = created;
  }
  return bundledRenderer;
}

function render(bytes, fileName, options) {
  const { limits, ...renderOptions } = options ?? {};
  const handle = call(() =>
    renderer().render(
      toBytes(bytes),
      toFileName(fileName),
      JSON.stringify(renderOptions),
      toLimitsJson(limits),
    ),
  );
  try {
    const summary = JSON.parse(handle.json);
    const pageImages = [];
    for (let index = 0; index < summary.pageImageCount; index += 1) {
      pageImages.push(handle.takePageImage(index));
    }
    return {
      format: summary.format,
      fidelity: summary.fidelity,
      pageCount: summary.pageCount,
      truncated: summary.truncated,
      pdf: handle.takePdf() ?? null,
      thumbnail: handle.takeThumbnail() ?? null,
      pageImages,
    };
  } finally {
    handle.free();
  }
}

function writeDocx(tree) {
  const { blocks, page, media, notes, headersFooters, sections, comments, objects, macroProject } = tree ?? {};
  const writer = new wasm.DocxWriter();
  try {
    for (const bytes of media ?? []) {
      writer.addMedia(toBytes(bytes));
    }
    for (const object of objects ?? []) {
      writer.addObject(object.media, toBytes(object.bytes), object.name ?? 'oleObject.bin', object.program);
    }
    if (macroProject !== undefined && macroProject !== null) {
      call(() => writer.setMacroProject(toBytes(macroProject)));
    }
    return call(() =>
      writer.write(
        JSON.stringify({ blocks: blocks ?? [], page, notes, headersFooters, sections, comments }),
      ),
    );
  } finally {
    writer.free();
  }
}

/** The tree in a writer with its images added, for `write` to turn into a file. */
function withTreeWriter(tree, write) {
  const { blocks, page, media, notes, headersFooters, sections, comments } = tree ?? {};
  const writer = new wasm.DocxWriter();
  try {
    for (const bytes of media ?? []) {
      writer.addMedia(toBytes(bytes));
    }
    const json = JSON.stringify({ blocks: blocks ?? [], page, notes, headersFooters, sections, comments });
    return call(() => write(writer, json));
  } finally {
    writer.free();
  }
}

function writeOdt(tree) {
  return withTreeWriter(tree, (writer, json) => writer.writeOdt(json));
}

function writeMarkdown(tree) {
  return withTreeWriter(tree, (writer, json) => writer.writeMarkdown(json));
}

function writeHtml(tree, title) {
  return withTreeWriter(tree, (writer, json) => writer.writeHtml(json, title === undefined ? '' : String(title)));
}

let sheetModule = null;

/** The spreadsheet module, loaded on the first sheet only. */
function sheets() {
  if (sheetModule === null) {
    sheetModule = require('./wasm/rely_office_sheet_wasm.js');
  }
  return sheetModule;
}

/** A spreadsheet being edited; its methods mirror the editor's actions. */
class SheetDocument {
  constructor(document) {
    this.document = document;
  }

  sheets() {
    return JSON.parse(call(() => this.document.sheetsJson()));
  }

  cells(sheet, { top, left, bottom, right }) {
    return JSON.parse(call(() => this.document.cellsJson(sheet, top, left, bottom, right)));
  }

  input(sheet, row, column) {
    return this.document.input(sheet, row, column);
  }

  setInput(sheet, row, column, text) {
    call(() => this.document.setInput(sheet, row, column, String(text)));
  }

  setInputs(sheet, inputs) {
    call(() => this.document.setInputs(sheet, JSON.stringify(inputs)));
  }

  setFormat(sheet, row, column, format) {
    call(() => this.document.setFormat(sheet, row, column, JSON.stringify(format)));
  }

  setColumnWidth(sheet, column, width) {
    call(() => this.document.setColumnWidth(sheet, column, width ?? -1));
  }

  setStyle(sheet, { top, left, bottom, right }, patch) {
    call(() => this.document.setStyle(sheet, top, left, bottom, right, JSON.stringify(patch ?? {})));
  }

  setBorders(sheet, { top, left, bottom, right }, placement, border) {
    call(() =>
      this.document.setBorders(sheet, top, left, bottom, right, String(placement), JSON.stringify(border ?? null)),
    );
  }

  clearStyles(sheet, { top, left, bottom, right }) {
    call(() => this.document.clearStyles(sheet, top, left, bottom, right));
  }

  styles() {
    return JSON.parse(call(() => this.document.stylesJson()));
  }

  merges(sheet) {
    return JSON.parse(call(() => this.document.mergesJson(sheet)));
  }

  definedNames() {
    return JSON.parse(call(() => this.document.definedNamesJson())).map(({ sheet, ...name }) =>
      sheet === null || sheet === undefined ? name : { ...name, sheet },
    );
  }

  setDefinedName(name, formula, sheet) {
    call(() => this.document.setDefinedName(name, sheet ?? undefined, formula));
  }

  removeDefinedName(name, sheet) {
    return this.document.removeDefinedName(name, sheet ?? undefined);
  }

  charts(sheet) {
    return JSON.parse(call(() => this.document.chartsJson(sheet)));
  }

  addChart(sheet, chart, placement) {
    return call(() => this.document.addChart(sheet, JSON.stringify(chart), JSON.stringify(placement)));
  }

  setChart(sheet, index, { chart, placement } = {}) {
    call(() =>
      this.document.setChart(
        sheet,
        index,
        chart === undefined ? undefined : JSON.stringify(chart),
        placement === undefined ? undefined : JSON.stringify(placement),
      ),
    );
  }

  removeChart(sheet, index) {
    call(() => this.document.removeChart(sheet, index));
  }

  chartForRange(sheet, { top, left, bottom, right }, type) {
    return JSON.parse(call(() => this.document.chartForRangeJson(sheet, top, left, bottom, right, type)));
  }

  comments(sheet) {
    return JSON.parse(call(() => this.document.commentsJson(sheet)));
  }

  setComment(sheet, row, column, text, author = '') {
    call(() => this.document.setComment(sheet, row, column, author, text));
  }

  startCommentThread(sheet, row, column, text, author = '', date = '') {
    call(() => this.document.startCommentThread(sheet, row, column, author, text, date));
  }

  replyToComment(sheet, row, column, text, author = '', date = '') {
    call(() => this.document.replyToComment(sheet, row, column, author, text, date));
  }

  setCommentResolved(sheet, row, column, resolved) {
    call(() => this.document.setCommentResolved(sheet, row, column, resolved));
  }

  removeCommentReply(sheet, row, column, reply) {
    call(() => this.document.removeCommentReply(sheet, row, column, reply));
  }

  mergeCells(sheet, { top, left, bottom, right }) {
    call(() => this.document.mergeCells(sheet, top, left, bottom, right));
  }

  unmergeCells(sheet, { top, left, bottom, right }) {
    call(() => this.document.unmergeCells(sheet, top, left, bottom, right));
  }

  setRowHeight(sheet, row, height) {
    call(() => this.document.setRowHeight(sheet, row, height ?? -1));
  }

  clearRange(sheet, { top, left, bottom, right }) {
    call(() => this.document.clearRange(sheet, top, left, bottom, right));
  }

  copyRange(sheet, { top, left, bottom, right }, targetSheet, row, column) {
    call(() => this.document.copyRange(sheet, top, left, bottom, right, targetSheet, row, column));
  }

  insertRows(sheet, at, count = 1) {
    call(() => this.document.insertRows(sheet, at, count));
  }

  deleteRows(sheet, at, count = 1) {
    call(() => this.document.deleteRows(sheet, at, count));
  }

  insertColumns(sheet, at, count = 1) {
    call(() => this.document.insertColumns(sheet, at, count));
  }

  deleteColumns(sheet, at, count = 1) {
    call(() => this.document.deleteColumns(sheet, at, count));
  }

  addSheet(name) {
    return call(() => this.document.addSheet(String(name)));
  }

  renameSheet(sheet, name) {
    call(() => this.document.renameSheet(sheet, String(name)));
  }

  removeSheet(sheet) {
    call(() => this.document.removeSheet(sheet));
  }

  conditionalFormats(sheet) {
    return JSON.parse(call(() => this.document.conditionalFormatsJson(sheet)));
  }

  setConditionalFormats(sheet, formats) {
    call(() => this.document.setConditionalFormats(sheet, JSON.stringify(formats ?? [])));
  }

  validations(sheet) {
    return JSON.parse(call(() => this.document.validationsJson(sheet)));
  }

  setValidations(sheet, validations) {
    call(() => this.document.setValidations(sheet, JSON.stringify(validations ?? [])));
  }

  conditionalLooks(sheet) {
    return JSON.parse(call(() => this.document.conditionalLooksJson(sheet)));
  }

  validation(sheet, row, column) {
    return JSON.parse(call(() => this.document.validationJson(sheet, row, column)));
  }

  invalidCells(sheet) {
    return JSON.parse(call(() => this.document.invalidCellsJson(sheet)));
  }

  fillRange(sheet, source, target) {
    call(() =>
      this.document.fillRange(
        sheet,
        source.top,
        source.left,
        source.bottom,
        source.right,
        target.top,
        target.left,
        target.bottom,
        target.right,
      ),
    );
  }

  setFrozen(sheet, rows, columns) {
    call(() => this.document.setFrozen(sheet, rows, columns));
  }

  sortRange(sheet, { top, left, bottom, right }, keys, hasHeader) {
    call(() => this.document.sortRange(sheet, top, left, bottom, right, JSON.stringify(keys ?? []), Boolean(hasHeader)));
  }

  setAutoFilter(sheet, window) {
    if (window === null || window === undefined) {
      call(() => this.document.clearAutoFilter(sheet));
      return;
    }
    const { top, left, bottom, right } = window;
    call(() => this.document.setAutoFilter(sheet, top, left, bottom, right));
  }

  setFilterColumn(sheet, column, shown) {
    call(() => this.document.setFilterColumn(sheet, column, JSON.stringify(shown ?? null)));
  }

  filterChoices(sheet, column) {
    return JSON.parse(call(() => this.document.filterChoicesJson(sheet, column)));
  }

  pictures(sheet) {
    return JSON.parse(call(() => this.document.picturesJson(sheet)));
  }

  pictureBytes(sheet, index) {
    return this.document.pictureBytes(sheet, index);
  }

  functionNames() {
    return JSON.parse(this.document.functionNamesJson());
  }

  /** Today's date for TODAY() and NOW(): a Date, a serial day count, or null to unset it. */
  setToday(today) {
    this.document.setToday(toSerial(today));
  }

  previewInput(text) {
    return this.document.previewInput(String(text));
  }

  save() {
    return call(() => this.document.save());
  }

  saveOds() {
    return call(() => this.document.saveOds());
  }

  saveCsv(sheet, separator) {
    return call(() => this.document.saveCsv(sheet, separator === undefined ? undefined : String(separator)));
  }

  delimiter() {
    return this.document.delimiter() ?? null;
  }

  macros() {
    return this.document.macros();
  }

  undo() {
    return this.document.undo();
  }

  redo() {
    return this.document.redo();
  }

  canUndo() {
    return this.document.canUndo();
  }

  canRedo() {
    return this.document.canRedo();
  }

  free() {
    this.document.free();
  }
}

/** Days since 30 December 1899, as spreadsheets count dates; -1 for none. */
function toSerial(today) {
  if (today === null || today === undefined) {
    return -1;
  }
  if (today instanceof Date) {
    const midnight = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
    const local = today.getHours() / 24 + today.getMinutes() / 1440 + today.getSeconds() / 86400;
    return (midnight - Date.UTC(1899, 11, 30)) / 86400000 + local;
  }
  return Number(today);
}

function createSheet(options) {
  const locale = options?.locale ?? 'it';
  return new SheetDocument(call(() => new (sheets().SheetDocument)(locale)));
}

function openSheet(bytes, fileName, options) {
  const locale = options?.locale ?? 'it';
  return new SheetDocument(
    call(() => sheets().SheetDocument.open(toBytes(bytes), toFileName(fileName), locale)),
  );
}

module.exports = {
  RelyOfficeError,
  detectFormat,
  extractText,
  readSheets,
  readDocumentTree,
  render,
  writeDocx,
  writeMarkdown,
  writeHtml,
  writeOdt,
  writeOdp,
  convertToDocx,
  convertToPptx,
  readPresentation,
  writePptx,
  createSheet,
  openSheet,
  version: wasm.version(),
};
